import Accordion from '../Accordion';

describe('Accordion', () => {
  describe('Рендеринг', () => {
    it('should render with default props', () => {
      render(<Accordion title="Test Title" data={[{ name: 'test', info: 'info' }]} />);

      expect(screen.getByText(/test/i)).toBeInTheDocument();
      expect(screen.getByText(/info/i)).toBeInTheDocument();
    });

    it('should render with disabled prop', () => {
      render(
        <Accordion
          title="Test Title"
          disabled
          data={[{ name: 'test', info: 'info' }]}
        />
      );

      expect(screen.queryByRole('checkbox')).not.toBeInTheDocument();
    });

    it('should render without data', () => {
      render(<Accordion title="Test Title" data={[]} />);

      expect(screen.queryAllByRole('checkbox')).toHaveLength(0);
    });

    it('should handle null data', () => {
      render(<Accordion title="Test Title" data={null} />);

      expect(screen.queryAllByRole('checkbox')).toHaveLength(0);
    });

    it('should handle undefined data', () => {
      render(<Accordion title="Test Title" data={undefined} />);

      expect(screen.queryAllByRole('checkbox')).toHaveLength(0);
    });
  });

  describe('Обработка событий', () => {
    let component;

    beforeEach(() => {
      const data = [
        { name: 'test1', info: 'info1' },
        { name: 'test2', info: 'info2' },
      ];
      component = render(
        <Accordion
          title="Test Title"
          data={data}
          checkedList={['test1']}
        />
      );
    });

    it('should check and uncheck a checkbox', async () => {
      const checkbox = screen.getByLabelText(/test2/i);

      await userEvent.click(checkbox);

      expect(screen.getByLabelText(/test2/i).checked).toEqual(true);
      expect(screen.getByLabelText(/test1/i).checked).toEqual(false);
    });
  });
});

