// ============================================
import React from 'react';
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import '@testing-library/jest-dom';
import Block from '../Block';

describe('Block', () => {
  describe('Рендеринг', () => {
    it('should render with default props', () => {
      render(<Block title="Test" />);
      expect(screen.getByText(/test/i)).toBeInTheDocument();
    });

    it('should render with custom children', () => {
      const child = <div data-testid="child">Child</div>;
      render(<Block title="Test" children={child} />);
      expect(screen.getByTestId('child')).toBeInTheDocument();
    });

    it('should render without hide button when withHide is false', () => {
      render(<Block title="Test" withHide={false} />);
      expect(screen.queryByRole('button')).not.toBeInTheDocument();
    });

    it('should render with hide button when withHide is true', () => {
      render(<Block title="Test" withHide={true} />);
      expect(screen.getByRole('button')).toBeInTheDocument();
    });

    it('should render with collapse chevron icon', () => {
      render(<Block title="Test" withHide={true} open={false} />);
      expect(screen.getByRole('button').querySelector('.MuiSvgIcon-root')).toBeInTheDocument();
    });

    it('should not render collapse chevron icon when open', () => {
      render(<Block title="Test" withHide={true} open={true} />);
      expect(screen.queryByRole('button').querySelector('.MuiSvgIcon-root')).not.toBeInTheDocument();
    });
  });

  describe('Обработка событий', () => {
    let onToggleMock;

    beforeEach(() => {
      onToggleMock = jest.fn();
    });

    it('should call onToggle when click on title', async () => {
      render(<Block title="Test" onToggle={onToggleMock} />);
      await userEvent.click(screen.getByText(/test/i));
      expect(onToggleMock).toHaveBeenCalledTimes(1);
    });

    it('should toggle collapse state', async () => {
      render(<Block title="Test" onToggle={onToggleMock} open={false} />);
      await userEvent.click(screen.getByText(/test/i));
      expect(onToggleMock).toHaveBeenCalledTimes(1);
      expect(screen.queryByRole('button').querySelector('.MuiSvgIcon-root')).toHaveAttribute('style', 'transform: rotate(0deg)');
    });
  });
});

