      data: [
        { id: 1, name: 'Test Task' },
        { id: 2, name: 'Another Test Task' }
      ]
    }));
  }),
);

beforeAll(() => server.listen());
afterEach(() => server.resetHandlers());
afterAll(() => server.close());

describe('App Integration Tests', () => {
