  const secondIconClr = getFontColor(color || theme.primary);

  const renderIcon = () => {
    if (variant === "add") {
      return AddIcon;
    } else if (variant === "error") {
      return ErrorIcon;
    } else if (variant === "success") {
      return SuccessIcon;
    } else {
      return null;
    }
  };
  const AddIcon = (
    <>
      <rect
        x="124.093"
        y="286.465"
        width="87.6744"
        height="13.4884"
