      style={{
        filter: settings.enableGlow
          ? `drop-shadow(0px 0px ${64 * scale}px ${taskIconClr}c8)`
          : "none",
      }}
    >
      <circle cx="130.837" cy="34.2327" r="26.7209" stroke={taskIconClr} stroke-width="14" />
      <rect
        y="51.7676"
