import ShortcutItem from "../ShortcutItem";

export default function ShortcutsTab() {
  const cmdOrCtrl = systemInfo.isAppleDevice ? "Cmd" : "Ctrl";

  return (
    <>
      <ShortcutItem
        name="Quick Export"
        description="Save all tasks and download as JSON file"
